from pathlib import Path

src = Path('eio26/EioClient.java')
s = src.read_text()


def rep(old, new, label, count=1):
    global s
    if old not in s:
        raise SystemExit('patch target not found: ' + label)
    s = s.replace(old, new, count)

if 'public static final String VERSION = "0.27.0";' not in s:
    rep('public static final String VERSION = "0.26.0";', 'public static final String VERSION = "0.27.0";', 'version')
    rep('public static final String BUILD_ID = "EIO-026-AREA1";', 'public static final String BUILD_ID = "EIO-027-STAGE1";', 'build id')

    rep('''    private static int areaNavIndex;\n    private static int areaMoveTicks;\n    private static int areaMinedThisPass;''', '''    private static int areaNavIndex;\n    private static int areaStageIndex;\n    private static int areaMoveTicks;\n    private static int areaMinedThisPass;''', 'area stage state')

    old_module = '''        mod("Area Miner", "Mining", "Mines a user-defined rectangular area to a chosen depth and can move through the selected coordinates.", -1)\n                .point("Corner A", "Stand at the first horizontal corner and left-click this row to set it here. Right-click clears it.")\n                .point("Corner B", "Stand at the opposite horizontal corner and left-click this row to set it here. Right-click clears it.")\n                .num("Depth", 8.0, 1.0, 64.0, 1.0, "Number of blocks to mine downward from the higher corner Y level.")\n                .num("Retarget Delay", 1.0, 1.0, 4.0, 1.0, "Ticks to release attack before starting the next area target.")\n                .num("Aim Timeout", 14.0, 4.0, 50.0, 1.0, "Ticks allowed to line up with a target before temporarily skipping it.")\n                .num("Move Timeout", 100.0, 20.0, 240.0, 5.0, "Ticks allowed to reach one navigation cell before moving to the next cell.")\n                .bool("Auto Move", true, "Move through the configured rectangle when no mineable block is currently in normal interaction range.")\n                .bool("Sprint", false, "Sprint while Area Miner is navigating between cells.")\n                .bool("Auto Jump", true, "Jump over simple one-block obstacles while Area Miner is moving.")\n                .bool("Exposed Only", true, "Mine only blocks with an air-adjacent face, exposing deeper layers progressively.")\n                .bool("Face Block", true, "Turn your view toward the current Area Miner target.");'''
    new_module = '''        mod("Area Miner", "Mining", "Clears a selected rectangle in serpentine tunnel lanes, finishing each 5-block-deep stage before descending to the next one.", -1)\n                .point("Corner A", "Stand at the first horizontal corner and left-click this row to set it here. Right-click clears it.")\n                .point("Corner B", "Stand at the opposite horizontal corner and left-click this row to set it here. Right-click clears it.")\n                .num("Depth", 10.0, 1.0, 64.0, 1.0, "Total depth below the surface. Area Miner processes this in fixed 5-block stages.")\n                .num("Retarget Delay", 1.0, 1.0, 4.0, 1.0, "Ticks to release attack before starting the next area target.")\n                .num("Aim Timeout", 14.0, 4.0, 50.0, 1.0, "Ticks allowed to line up with a target before temporarily skipping it.")\n                .num("Move Timeout", 100.0, 20.0, 240.0, 5.0, "Ticks allowed to reach one serpentine navigation cell before moving to the next cell.")\n                .bool("Auto Move", true, "Move through each lane of the configured rectangle after clearing the blocks immediately ahead.")\n                .bool("Sprint", false, "Sprint while Area Miner is navigating through a cleared lane.")\n                .bool("Auto Jump", true, "Jump over simple one-block obstacles while Area Miner is moving.")\n                .bool("Exposed Only", true, "Mine only exposed blocks; each 5-block stage is revisited until it is completely clear.")\n                .bool("Face Block", true, "Turn your view toward the current straight-ahead Area Miner target.");'''
    rep(old_module, new_module, 'Area Miner module')

    start = s.index('    private static String areaStatus(Mod area) {')
    end = s.index('    private static void faceHorizontal(Player player, double x, double z) {', start)
    replacement = '''    private static String areaStatus(Mod area) {\n        AreaRegion region = areaRegion(area);\n        if (region == null) return "Area Miner: set Corner A and Corner B";\n        if (!region.supportedSize()) return "Area Miner: maximum supported area is " + AreaRegion.MAX_SIDE + "x" + AreaRegion.MAX_SIDE;\n        int stage = Math.max(0, Math.min(areaStageIndex, region.stageCount() - 1));\n        String stageText = "stage " + (stage + 1) + "/" + region.stageCount()\n                + " Y " + region.stageTopY(stage) + ".." + region.stageBottomY(stage);\n        return "Area Miner: " + region.summary() + " | " + stageText\n                + (areaComplete ? " | complete" : " | lane " + (Math.min(areaNavIndex, Math.max(0, region.navigationCells() - 1)) + 1) + "/" + region.navigationCells());\n    }\n\n    private static void resetAreaRuntime() {\n        areaMineTarget = null;\n        areaMineRearmTicks = 0;\n        areaMineAimTicks = 0;\n        areaNavIndex = 0;\n        areaStageIndex = 0;\n        areaMoveTicks = 0;\n        areaMinedThisPass = 0;\n        areaMoveRequested = false;\n        areaComplete = false;\n        AREA_MINE_SKIPPED.clear();\n    }\n\n    private static boolean validAreaMineTarget(Minecraft mc, Mod area, BlockPos pos) {\n        if (mc.player == null || mc.level == null || pos == null) return false;\n        AreaRegion region = areaRegion(area);\n        if (region == null || !region.supportedSize() || !region.containsStage(pos, areaStageIndex)) return false;\n        if (!withinVanillaBlockRange(mc, pos)) return false;\n        var state = mc.level.getBlockState(pos);\n        if (state.isAir() || state.getDestroySpeed(mc.level, pos) < 0.0f) return false;\n        return !area.bool("Exposed Only").value || isExposedBlock(mc, pos);\n    }\n\n    private static BlockPos findAreaMineTarget(Minecraft mc, Mod area) {\n        if (mc.player == null || mc.level == null) return null;\n        AreaRegion region = areaRegion(area);\n        if (region == null || !region.supportedSize() || areaStageIndex >= region.stageCount()) return null;\n        int cells = region.navigationCells();\n        if (cells <= 0) return null;\n        int baseIndex = Math.max(0, Math.min(areaNavIndex, cells - 1));\n        BlockPos best = null;\n        double bestScore = Double.MAX_VALUE;\n        int lookAhead = Math.min(3, cells - baseIndex);\n        for (int step = 0; step < lookAhead; step++) {\n            BlockPos lane = region.navigationCell(baseIndex + step, mc.player.blockPosition().getY());\n            if (lane == null) continue;\n            for (int y = region.stageTopY(areaStageIndex); y >= region.stageBottomY(areaStageIndex); y--) {\n                BlockPos pos = new BlockPos(lane.getX(), y, lane.getZ());\n                if (AREA_MINE_SKIPPED.contains(pos) || !validAreaMineTarget(mc, area, pos)) continue;\n                double dx = pos.getX() + 0.5 - mc.player.getX();\n                double dy = pos.getY() + 0.5 - mc.player.getEyeY();\n                double dz = pos.getZ() + 0.5 - mc.player.getZ();\n                double score = step * 1000.0 + dx * dx + dy * dy + dz * dz;\n                if (score < bestScore) { bestScore = score; best = pos.immutable(); }\n            }\n        }\n        return best;\n    }\n\n    private static boolean areaStageHasBlocks(Minecraft mc, Mod area, AreaRegion region, int stage) {\n        if (mc.level == null || region == null || stage < 0 || stage >= region.stageCount()) return false;\n        for (int y = region.stageTopY(stage); y >= region.stageBottomY(stage); y--) {\n            for (int z = region.minZ; z <= region.maxZ; z++) {\n                for (int x = region.minX; x <= region.maxX; x++) {\n                    BlockPos pos = new BlockPos(x, y, z);\n                    var state = mc.level.getBlockState(pos);\n                    if (!state.isAir() && state.getDestroySpeed(mc.level, pos) >= 0.0f) return true;\n                }\n            }\n        }\n        return false;\n    }\n\n    private static boolean advanceAreaStageIfReady(Minecraft mc, Mod area, AreaRegion region) {\n        if (areaNavIndex < region.navigationCells()) return false;\n        if (areaMinedThisPass > 0) {\n            areaNavIndex = 0;\n            areaMinedThisPass = 0;\n            areaMoveTicks = 0;\n            AREA_MINE_SKIPPED.clear();\n            return true;\n        }\n        if (areaStageHasBlocks(mc, area, region, areaStageIndex)) {\n            area.enabled = false;\n            save();\n            notifyMessage("AREA MINER PAUSED: STAGE " + (areaStageIndex + 1) + " HAS UNREACHABLE BLOCKS", 0xFFFFB36B, 4200L);\n            appendDiagnostic("AREA_MINER stalled stage=" + (areaStageIndex + 1));\n            return true;\n        }\n        areaStageIndex++;\n        areaNavIndex = 0;\n        areaMoveTicks = 0;\n        areaMinedThisPass = 0;\n        areaMineTarget = null;\n        areaMineAimTicks = 0;\n        areaMineRearmTicks = 1;\n        AREA_MINE_SKIPPED.clear();\n        if (areaStageIndex >= region.stageCount()) {\n            areaComplete = true;\n            area.enabled = false;\n            save();\n            notifyMessage("AREA MINER COMPLETE", 0xFF75DDA8, 3200L);\n            return true;\n        }\n        notifyMessage("AREA MINER: STARTING STAGE " + (areaStageIndex + 1) + "/" + region.stageCount(), 0xFF74C8F0, 2200L);\n        return true;\n    }\n\n    private static boolean updateAreaNavigation(Minecraft mc, Mod area) {\n        if (mc.player == null || mc.level == null || !areaConfigured(area) || areaComplete) return false;\n        AreaRegion region = areaRegion(area);\n        if (region == null || areaStageIndex >= region.stageCount()) return false;\n        if (areaMineTarget != null || areaMineRearmTicks > 0) { areaMoveTicks = 0; return false; }\n        BlockPos reachable = findAreaMineTarget(mc, area);\n        if (reachable != null) {\n            areaMineTarget = reachable;\n            areaMineAimTicks = 0;\n            areaMoveTicks = 0;\n            return false;\n        }\n\n        double px = mc.player.getX(), pz = mc.player.getZ();\n        boolean outside = px < region.minX + 0.15 || px > region.maxX + 0.85\n                || pz < region.minZ + 0.15 || pz > region.maxZ + 0.85;\n        double goalX, goalZ;\n        if (outside) {\n            goalX = region.clampX(px) + 0.5;\n            goalZ = region.clampZ(pz) + 0.5;\n        } else {\n            if (advanceAreaStageIfReady(mc, area, region)) return false;\n            BlockPos nav = region.navigationCell(areaNavIndex, mc.player.blockPosition().getY());\n            if (nav == null) return false;\n            goalX = nav.getX() + 0.5;\n            goalZ = nav.getZ() + 0.5;\n        }\n\n        double dx = goalX - px, dz = goalZ - pz;\n        double distance = Math.sqrt(dx * dx + dz * dz);\n        if (!outside && distance < 0.72) {\n            areaNavIndex++;\n            areaMoveTicks = 0;\n            return false;\n        }\n        if (++areaMoveTicks >= Math.max(20, (int) Math.round(area.num("Move Timeout").value))) {\n            if (!outside) areaNavIndex++;\n            areaMoveTicks = 0;\n            return false;\n        }\n        faceHorizontal(mc.player, goalX, goalZ);\n        return distance > 0.45;\n    }\n\n'''
    s = s[:start] + replacement + s[end:]

    rep('''            else if (setting instanceof MobListSetting ml) ml.reset();\n            else if (setting instanceof PointSetting point) point.reset();\n                else if (setting instanceof PointSetting point) point.reset();''', '''            else if (setting instanceof MobListSetting ml) ml.reset();\n            else if (setting instanceof PointSetting point) point.reset();''', 'duplicate point reset')

    rep('''            else if (setting instanceof NumSetting n) n.set(n.defaultValue);\n            else if (setting instanceof MobListSetting ml) ml.reset();\n        }''', '''            else if (setting instanceof NumSetting n) n.set(n.defaultValue);\n            else if (setting instanceof MobListSetting ml) ml.reset();\n            else if (setting instanceof PointSetting point) point.reset();\n        }''', 'module point reset')

src.write_text(s)

# Upgrade region math with explicit fixed five-block stages.
area = Path('eio26/com/eio/client/AreaRegion.java')
area.write_text('''package com.eio.client;\n\nimport net.minecraft.core.BlockPos;\n\n/** Immutable horizontal quarry bounds plus staged top-down mining depth. */\nfinal class AreaRegion {\n    static final int MAX_SIDE = 128;\n    static final int STAGE_DEPTH = 5;\n\n    final int minX;\n    final int maxX;\n    final int minZ;\n    final int maxZ;\n    final int topY;\n    final int bottomY;\n\n    private AreaRegion(int minX, int maxX, int minZ, int maxZ, int topY, int bottomY) {\n        this.minX = minX;\n        this.maxX = maxX;\n        this.minZ = minZ;\n        this.maxZ = maxZ;\n        this.topY = topY;\n        this.bottomY = bottomY;\n    }\n\n    static AreaRegion from(BlockPos a, BlockPos b, int depth) {\n        if (a == null || b == null) return null;\n        int safeDepth = Math.max(1, Math.min(64, depth));\n        int top = Math.max(a.getY(), b.getY());\n        return new AreaRegion(\n                Math.min(a.getX(), b.getX()), Math.max(a.getX(), b.getX()),\n                Math.min(a.getZ(), b.getZ()), Math.max(a.getZ(), b.getZ()),\n                top, top - safeDepth + 1);\n    }\n\n    int width() { return maxX - minX + 1; }\n    int length() { return maxZ - minZ + 1; }\n    int depth() { return topY - bottomY + 1; }\n    int stageCount() { return (depth() + STAGE_DEPTH - 1) / STAGE_DEPTH; }\n\n    int stageTopY(int stage) {\n        int safe = Math.max(0, Math.min(stageCount() - 1, stage));\n        return topY - safe * STAGE_DEPTH;\n    }\n\n    int stageBottomY(int stage) {\n        return Math.max(bottomY, stageTopY(stage) - STAGE_DEPTH + 1);\n    }\n\n    boolean supportedSize() {\n        return width() > 0 && length() > 0 && width() <= MAX_SIDE && length() <= MAX_SIDE;\n    }\n\n    int navigationCells() {\n        if (!supportedSize()) return 0;\n        return width() * length();\n    }\n\n    boolean contains(BlockPos pos) {\n        return pos != null\n                && pos.getX() >= minX && pos.getX() <= maxX\n                && pos.getZ() >= minZ && pos.getZ() <= maxZ\n                && pos.getY() >= bottomY && pos.getY() <= topY;\n    }\n\n    boolean containsStage(BlockPos pos, int stage) {\n        return contains(pos) && stage >= 0 && stage < stageCount()\n                && pos.getY() <= stageTopY(stage) && pos.getY() >= stageBottomY(stage);\n    }\n\n    int clampX(double x) { return Math.max(minX, Math.min(maxX, (int) Math.floor(x))); }\n    int clampZ(double z) { return Math.max(minZ, Math.min(maxZ, (int) Math.floor(z))); }\n\n    BlockPos navigationCell(int index, int y) {\n        int cells = navigationCells();\n        if (cells <= 0) return null;\n        int normalized = Math.floorMod(index, cells);\n        int row = normalized / width();\n        int col = normalized % width();\n        if ((row & 1) != 0) col = width() - 1 - col;\n        int navY = Math.max(bottomY, Math.min(topY, y));\n        return new BlockPos(minX + col, navY, minZ + row);\n    }\n\n    String summary() {\n        return minX + "," + minZ + " -> " + maxX + "," + maxZ\n                + " | Y " + topY + ".." + bottomY + " | " + width() + "x" + length() + "x" + depth();\n    }\n}\n''')

# Expand region regression coverage for fixed five-block stages.
test = Path('src/test/java/com/eio/client/AreaRegionTest.java')
t = test.read_text()
if 'splitsDepthIntoFiveBlockStages' not in t:
    insert = '''\n    @Test\n    void splitsDepthIntoFiveBlockStages() {\n        AreaRegion r = AreaRegion.from(new BlockPos(0, 70, 0), new BlockPos(2, 70, 2), 12);\n        assertEquals(3, r.stageCount());\n        assertEquals(70, r.stageTopY(0));\n        assertEquals(66, r.stageBottomY(0));\n        assertEquals(65, r.stageTopY(1));\n        assertEquals(61, r.stageBottomY(1));\n        assertEquals(60, r.stageTopY(2));\n        assertEquals(59, r.stageBottomY(2));\n        assertTrue(r.containsStage(new BlockPos(1, 67, 1), 0));\n        assertFalse(r.containsStage(new BlockPos(1, 65, 1), 0));\n        assertTrue(r.containsStage(new BlockPos(1, 65, 1), 1));\n    }\n'''
    t = t.replace('\n    @Test\n    void rejectsOversizedNavigationArea()', insert + '\n    @Test\n    void rejectsOversizedNavigationArea()', 1)
    test.write_text(t)

# Version metadata.
gp = Path('gradle.properties')
g = gp.read_text()
if 'mod_version=0.26.0+26.3' in g:
    g = g.replace('mod_version=0.26.0+26.3', 'mod_version=0.27.0+26.3', 1)
elif 'mod_version=0.27.0+26.3' not in g:
    raise SystemExit('unexpected gradle version')
gp.write_text(g)
